func makeTestBatches(t *testing.T) []arrow.Record {
	t.Helper()
	alloc := memory.NewGoAllocator()
	schema := arrow.NewSchema([]arrow.Field{
		{Name: "v", Type: arrow.BinaryTypes.String},
		{Name: "i", Type: arrow.PrimitiveTypes.Int32},
	}, nil)
	b := array.NewRecordBuilder(alloc, schema)
	defer b.Release()
	for i := 0; i < 20; i++ {
		b.Field(0).(*array.StringBuilder).Append(fmt.Sprintf("test%d", i))
		b.Field(1).(*array.Int32Builder).Append(int32(i))
	}
	rec := b.NewRecord()
	return []arrow.Record{rec}
}

func makeTestBatchesAndBytes(t *testing.T) ([]arrow.Record, []byte) {
	t.Helper()
	batches := makeTestBatches(t)
	data, err := api.WriteArrowIPC(batches)
	if err != nil {
		t.Fatalf("failed to write Arrow IPC: %v", err)
	}
	return batches, data
}

